/**
 * Weekday demand shape (plans/01 §8, plans/04 §1.3).
 *
 * `wd[category][dow]` is a multiplier on the average daily demand λ, always
 * normalized to a mean of 1 over the seven days so that the shape moves
 * demand around without changing its weekly total.
 *
 * Three modes:
 *  - `flat`  — every day is the average day.
 *  - `prior` — a documented grocery prior (weekend peak, weekday lunch peak
 *               for deli). These are assumptions, not data.
 *  - `uci`   — 50% UCI Online Retail II shape + 50% prior. The shape is
 *               generated by `scripts/build_weekday_index.py`; if the JSON
 *               carries `monToSun: null` (data not generated) this mode falls
 *               back to the prior, so the app never claims data it does not
 *               have.
 */

import type { Category } from "./types";
import weekdayIndexData from "./data/weekday_index.json";

export interface WeekdayIndex {
  source: string;
  monToSun: number[] | null;
}

export const WEEKDAY_INDEX: WeekdayIndex = weekdayIndexData as WeekdayIndex;

export type WeekdayMode = "uci" | "prior" | "flat";

export const DOW_LABELS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"] as const;

/**
 * Grocery prior per category, Mon→Sun (plans/04 §1.3). Assumption A3.
 * Each vector already has a mean of 1; the normalizer keeps it that way.
 */
export const CATEGORY_PRIOR: Record<Category, number[]> = {
  Bakery: [0.95, 0.9, 0.9, 0.95, 1.05, 1.2, 1.05],
  Dairy: [0.95, 0.9, 0.95, 1.0, 1.05, 1.15, 1.0],
  Produce: [0.9, 0.9, 0.95, 1.0, 1.05, 1.25, 0.95],
  "Meat & Fish": [0.85, 0.85, 0.9, 1.0, 1.15, 1.25, 1.0],
  Deli: [1.1, 1.05, 1.05, 1.05, 1.1, 0.9, 0.75],
};

/** Weekday of an absolute simulation day: 0 = Monday. Absolute day 7 is a Monday. */
export function dowOf(day: number): number {
  return ((day % 7) + 7) % 7;
}

/** Scale a vector so its mean is exactly 1. */
export function normalizeToMeanOne(values: number[]): number[] {
  const mean = values.reduce((sum, value) => sum + value, 0) / values.length;
  if (!Number.isFinite(mean) || mean === 0) return values.slice();
  return values.map((value) => value / mean);
}

/**
 * The weekday multiplier vector for a category under the given mode.
 *
 * `uciShape` is the optional seven-value UCI extract; pass `null` (or leave it
 * out when the data file has none) to fall back to the grocery prior.
 */
export function weekdayShape(
  category: Category,
  mode: WeekdayMode,
  uciShape: number[] | null = WEEKDAY_INDEX.monToSun,
): number[] {
  if (mode === "flat") return [1, 1, 1, 1, 1, 1, 1];

  const prior = CATEGORY_PRIOR[category];
  if (mode === "prior" || !uciShape || uciShape.length !== 7) {
    return normalizeToMeanOne(prior);
  }

  const blended = prior.map((value, i) => 0.5 * uciShape[i] + 0.5 * value);
  return normalizeToMeanOne(blended);
}
